package library_book_service.book_db;

import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import javax.sql.DataSource;
import library_book_service.config.RemoteConfig;
import library_book_service.security.SecretsResolver;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * HikariCP {@code DataSource} configuration for the 'bookDb' RDBMS block (postgres). Every RDBMS
 * block gets its own explicitly-named bean -- no {@code @Primary} guess across multi-block
 * services.
 *
 * <p>Auto-generated by datrix-codegen-java. Do not edit manually.
 */
@Configuration
public class BookDbDataSourceConfig {

  @Bean(name = "book_dbDataSource")
  public DataSource book_dbDataSource(RemoteConfig remoteConfig, SecretsResolver secretsResolver) {
    String host = remoteConfig.getBookDbHost();
    int port = remoteConfig.getBookDbPort();
    String database = remoteConfig.getBookDbDatabase();
    String username = remoteConfig.getBookDbUser();

    String jdbcUrl = "jdbc:postgresql://" + host + ":" + port + "/" + database;

    HikariConfig hikariConfig = new HikariConfig();
    hikariConfig.setJdbcUrl(jdbcUrl);
    hikariConfig.setDriverClassName("org.postgresql.Driver");
    hikariConfig.setUsername(username);
    hikariConfig.setPassword(secretsResolver.getSecret("book_db_password"));
    hikariConfig.setMaximumPoolSize(20);

    return new HikariDataSource(hikariConfig);
  }
}
